# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, offset=4):
    return [v + offset for v in xs]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(gather(fold(digest(raw))))

